import { t as getActiveMembership } from "../../../../chunks/group-membership.js";
import { t as client } from "../../../../chunks/prisma.js";
import { s as requireLogin } from "../../../../chunks/auth.js";
import { n as create } from "../../../../chunks/list.js";
import { redirect } from "@sveltejs/kit";
// src/routes/wishlists/me/+page.server.ts
var load = async () => {
	const user = requireLogin();
	const activeMembership = await getActiveMembership(user);
	let list = await client.list.findFirst({
		select: { id: true },
		where: {
			ownerId: user.id,
			groupId: activeMembership.groupId,
			notForMe: false
		}
	});
	if (!list) list = await create(user.id, activeMembership.groupId);
	redirect(302, `/lists/${list.id}`);
};
export { load };
